sqlReaderQuery.value:
@concat(
    'SELECT * FROM ', item().SourceSchema, '.', item().SourceTable,
    if(equals(item().LoadType, 'Incremental'), 
       concat(' WHERE ', item().WatermarkColumn, ' > ''', item().last_watermark, ''''), 
       ''
    )
)

storedProcedureName.value:
UPDATE ctl.PipelineMetadata
SET last_watermark = SYSUTCDATETIME()
WHERE Id = @{item().Id} AND LoadType = 'Incremental';
